// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Precondition: owner 2's pet carries no nickname.
    const ownerResponse = await page.request.get(`${baseUrl}/petclinic/api/owners/2`);
    expect(ownerResponse.status()).toBe(200);
    const owner = await ownerResponse.json();
    expect(owner.pets[0].name).toBe("Basil");
    expect(owner.pets[0].nickname).toBeUndefined();

    await page.goto(`${baseUrl}/owners/2`);

    // Guard: the pet list must actually render before the absence check below,
    // otherwise "no Nickname row" would pass vacuously on a blank page.
    await expect(page.locator("main")).toContainText("Basil");

    // Basil has no nickname, so the pet list should not render a Nickname row for it.
    await expect(page.locator("main")).not.toContainText("Nickname");
});
